import React,{useEffect,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import './style.css';
import './integrations.css';
import {money} from './format.js';

const API=import.meta.env.VITE_API_ORIGIN||'';
const nav=[
  ['home','⌂','Home'],['store','▣','My Store'],['success','☆','Success'],['income','$','Income'],
  ['analytics','↗','Analytics'],['customers','♙','Customers'],['community','◎','Community'],
  ['more','•••','More'],['settings','⚙','Settings']
];
const PRODUCT_VISUALS={
  'lead-magnet':['🎁','Lead magnet','Collect an email with a free resource'],
  'digital-download':['⬇','Digital download','Sell a file, template, or guide'],
  meeting:['📅','Meeting','Let buyers book time with you'],
  fulfillment:['📦','Fulfillment','Deliver a custom service or result'],
  course:['🎓','Course','Organize lessons into a learning path'],
  membership:['↻','Membership','Offer recurring subscriber access'],
  webinar:['▶','Webinar','Host a scheduled live event'],
  community:['👥','Community','Sell access to a private group'],
  'url-media':['🏷️','Promotion / external link','Share a sponsor, affiliate, shop, or media link']
};
const THEME_PRESETS={
  violet:{label:'Violet',accent:'#6842d7'},sunset:{label:'Sunset',accent:'#e85d3f'},
  mint:{label:'Mint',accent:'#16856b'},midnight:{label:'Midnight',accent:'#24213f'}
};
const productVisual=type=>PRODUCT_VISUALS[type]||['◆',type?.replaceAll('-',' ')||'Product','Creator offer'];
const designFromStore=store=>({title:store.title||'',tagline:store.tagline||'',theme:store.theme||'violet',accentColor:store.accent_color||'#6842d7',backgroundStyle:store.background_style||'soft-gradient',buttonStyle:store.button_style||'rounded',fontStyle:store.font_style||'modern',showProducts:store.show_products!==false,showLinks:store.show_links!==false});
const route=()=>location.pathname.startsWith('/dashboard')?(location.pathname.split('/')[2]||'home'):null;

async function request(path,options){
  const response=await fetch(`${API}${path}`,{credentials:'include',...options,headers:{'Content-Type':'application/json',...(options?.headers||{})}});
  if(!response.ok){const error=new Error((await response.json().catch(()=>({}))).error||`Request failed: ${response.status}`);error.status=response.status;throw error}
  return response.status===204?null:response.json();
}

async function uploadProductFile(productId,file,kind){
  const body=new FormData();body.append('file',file);
  const response=await fetch(`${API}/api/v1/products/${productId}/files?kind=${encodeURIComponent(kind)}`,{method:'POST',credentials:'include',body});
  if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||`Upload failed: ${response.status}`)}
  return response.json();
}

const defaultProductConfiguration=type=>({
  'digital-download':{deliveryMode:'upload',redirectUrl:''},
  'lead-magnet':{deliveryMode:'upload',redirectUrl:'',collectPhone:false},
  meeting:{location:'google-meet',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,durationMinutes:60,maxAttendees:1,minNoticeHours:12,bufferMinutes:15,availability:'Monday-Friday, 9:00 AM-5:00 PM'},
  webinar:{location:'google-meet',startsAt:'',durationMinutes:60,capacity:100},
  course:{modules:[{title:'Module 1',lessons:[{title:'Lesson 1',videoUrl:'',description:''}]}],dripDays:0},
  membership:{billingInterval:'monthly',memberBenefits:''},
  fulfillment:{turnaroundDays:3,buyerInstructions:'',deliveryFormat:'file-upload'},
  community:{memberBenefits:'',welcomeMessage:''}
}[type]||{});
const productConfiguration=product=>{try{return {...defaultProductConfiguration(product?.type),...JSON.parse(product?.configuration_json||'{}')}}catch{return defaultProductConfiguration(product?.type)}};

function App(){
  const [section,setSection]=useState(route());
  const [account,setAccount]=useState(null);
  useEffect(()=>{const pop=()=>setSection(route());addEventListener('popstate',pop);return()=>removeEventListener('popstate',pop)},[]);
  useEffect(()=>{if(section)request('/api/auth/me').then(setAccount).catch(()=>setAccount(false))},[section]);
  if(location.pathname==='/login')return <Login onSuccess={()=>location.assign('/dashboard/')}/>;
  if(!section) return <PublicStore/>;
  if(account===null)return <div className="public-loading">Checking your session…</div>;
  if(account===false)return <Login onSuccess={setAccount}/>;
  const go=id=>{history.pushState({},'',`/dashboard/${id==='home'?'':id}`);setSection(id)};
  return <div className="app-shell">
    <aside className="sidebar">
      <a className="brand" onClick={()=>go('home')}><span>CS</span><b>Creator Store</b></a>
      <nav>{nav.map(([id,icon,label])=><button key={id} className={section===id?'active':''} onClick={()=>go(id)}><i>{icon}</i>{label}{id==='success'&&<em>New</em>}</button>)}</nav>
      <div className="account"><div className="avatar small">{account.displayName?.[0]||'C'}</div><span><b>{account.displayName}</b><small>@{account.handle}</small></span></div>
    </aside>
    <main className="workspace"><Topbar section={section} account={account}/><Section key={section} id={section} account={account}/></main>
  </div>
}

function Topbar({section,account}){return <header className="topbar"><div><span className="eyebrow">Workspace</span><b>{nav.find(x=>x[0]===section)?.[2]||section}</b></div><div className="top-actions"><a href={`/${account.handle}`} target="_blank">View store ↗</a><button className="icon-button" aria-label="Notifications">♢</button></div></header>}

function Section({id,account}){
  const endpoints={home:'dashboard',store:'store',success:'success',income:'income',analytics:'analytics',customers:'customers',more:'more',settings:'settings'};
  const [data,setData]=useState(null),[error,setError]=useState('');
  const load=()=>{setData(null);setError('');if(!endpoints[id]){setData({});return}request(`/api/v1/${endpoints[id]}`).then(setData).catch(e=>setError(e.message))};
  useEffect(load,[id]);
  if(error)return <State title="Could not load this section" body={error} action={load}/>;
  if(!data)return <div className="skeleton-grid"><i/><i/><i/></div>;
  if(id==='home')return <Home data={data} account={account}/>;
  if(id==='store')return <Store data={data} reload={load} account={account}/>;
  if(id==='success')return <Success data={data}/>;
  if(id==='income')return <Income data={data}/>;
  if(id==='analytics')return <Analytics data={data}/>;
  if(id==='customers')return <Customers data={data} reload={load}/>;
  if(id==='community')return <Community/>;
  if(id==='more')return <More data={data}/>;
  if(id==='settings')return <Settings data={data}/>;
  return null;
}

function PageHead({title,subtitle,actions}){return <div className="page-head"><div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div>{actions}</div>}</div>}
function Metric({label,value,detail}){return <article className="metric"><span>{label}</span><strong>{value}</strong>{detail&&<small>{detail}</small>}</article>}

function Home({data,account}){const m=data.metrics;return <>
  <PageHead title={`Good morning, ${account.displayName}`} subtitle="Here’s what is happening in your creator business." actions={<button className="primary">Create product</button>}/>
  {!data.store.payouts_enabled&&<div className="notice"><b>External real-money setup required.</b><span>Connect a test Razorpay account and verify webhooks before accepting INR payments.</span><button>Open settings</button></div>}
  <section className="home-spotlight"><div><span className="eyebrow">Your creator command center</span><h2>Build the offer your audience cannot scroll past.</h2><p>Publish your strongest products, pin the hot deals, and send every visitor to one polished destination.</p><div className="spotlight-actions"><a className="primary" href="/dashboard/store">Open My Store</a><a className="secondary" href={`/${account.handle}`} target="_blank">View customer page ↗</a></div></div><div className="spotlight-art" aria-hidden="true"><span>HOT</span><b>YOUR<br/>STORE</b><i>↗</i></div></section>
  <div className="metrics"><Metric label="Store visits" value={m.visits}/><Metric label="Leads" value={m.leads}/><Metric label="Orders" value={m.orders}/><Metric label="Revenue" value={money(m.revenue_subunits)}/></div>
  <div className="two-column"><section className="panel"><h2>Get ready to sell</h2><div className="checklist">{data.checklist.map(x=><div key={x.id}><span className={x.complete?'done':''}>{x.complete?'✓':'○'}</span><b>{x.label}</b><small>{x.complete?'Complete':'Next step'}</small></div>)}</div></section>
  <section className="panel"><h2>Quick actions</h2><div className="action-grid"><button><b>＋ Add a product</b><small>Publish an offer in minutes</small></button><button><b>↗ Market your products</b><small>Plan your next launch</small></button><button><b>✦ Ask Creator Coach</b><small>Get practical ideas</small></button></div></section></div>
  </>}

function Store({data,reload,account}){const [tab,setTab]=useState('Store'),[open,setOpen]=useState(false),[editingPromotion,setEditingPromotion]=useState(null),[design,setDesign]=useState(()=>designFromStore(data.store));const saveDesign=async next=>{const saved=await request('/api/v1/store',{method:'PATCH',body:JSON.stringify(next)});const normalized=designFromStore(saved);setDesign(normalized);return normalized};const removePromotion=async id=>{if(!confirm('Delete this promotion? Its click history will also be removed.'))return;await request(`/api/v1/promotions/${id}`,{method:'DELETE'});reload()};const movePromotion=async(p,delta)=>{await request(`/api/v1/promotions/${p.id}`,{method:'PATCH',body:JSON.stringify(promotionPayload({...p,position:Number(p.position)+delta}))});reload()};const removeProduct=async id=>{if(!confirm('Delete this product?'))return;try{await request(`/api/v1/products/${id}`,{method:'DELETE'});reload()}catch(error){alert(error.message)}};const toggleProductPin=async p=>{try{await request(`/api/v1/products/${p.id}/pin?pinned=${!p.pinned}`,{method:'PATCH'});reload()}catch(error){alert(error.message)}};const togglePromotionPin=async p=>{try{await request(`/api/v1/promotions/${p.id}/pin?pinned=${!p.pinned}`,{method:'PATCH'});reload()}catch(error){alert(error.message)}};return <>
  <PageHead title="My Store" subtitle="Build, organize, and publish your offers." actions={<><a className="button secondary" href={`/${account.handle}`} target="_blank">Preview</a><button className="primary" onClick={()=>setOpen(true)}>＋ Add product</button></>}/>
  <div className="tabs">{['Store','Landing Pages','Edit Design'].map(x=><button className={tab===x?'selected':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>
  {tab==='Store'?<div className="store-layout"><section className="panel"><div className="store-profile"><div className="avatar">{design.title?.[0]||account.displayName?.[0]||'C'}</div><div><h2>{design.title}</h2><p>{design.tagline}</p></div><span className="pill">{data.store.published?'Published':'Draft'}</span></div><h3>Products and services</h3><div className="product-list">{data.products.map(p=>{const visual=productVisual(p.type);return <article className={p.pinned?'pinned-item':''} key={`product-${p.id}`}><div className="product-art">{visual[0]}</div><div><b>{p.pinned&&<span className="pin-label">📌 Pinned</span>}{p.title}</b><small>{visual[1]} · {money(p.price_subunits,data.store.currency)}</small></div><span className={`status ${p.status}`}>{p.status}</span>
<div className="row-actions"><button type="button" className={`pin-row-action ${p.pinned?'active-pin':''}`} disabled={p.status!=='published'} title={p.status!=='published'?'Publish this product before pinning':p.pinned?'Unpin product':'Pin product as a hot offer'} onClick={()=>toggleProductPin(p)}>{p.status!=='published'?'Publish first':p.pinned?'Unpin':'📌 Pin'}</button><button type="button" title="Edit product" onClick={()=>setOpen(p)}>✎</button><button type="button" className="danger-action" title="Delete product" onClick={()=>removeProduct(p.id)}>×</button></div></article>})}</div><div className="section-title"><div><h3>Promotions and external links</h3><small>Affiliate offers redirect to the merchant; they do not use your checkout.</small></div><button className="secondary small-button" onClick={()=>setOpen(true)}>＋ Add</button></div><div className="product-list">{data.promotions.length?data.promotions.map(p=><article className={p.pinned?'pinned-item':''} key={`promotion-${p.id}`}><div className="product-art">🏷️</div><div><b>{p.pinned&&<span className="pin-label">📌 Pinned</span>}{p.title}</b><small>{p.brand_name||'External link'}{p.offer_text?` · ${p.offer_text}`:''}</small></div><span className={`status ${p.published?'published':'draft'}`}>{p.published?'published':'draft'}</span>
<div className="row-actions"><button type="button" className={`pin-row-action ${p.pinned?'active-pin':''}`} disabled={!p.published} title={!p.published?'Publish this promotion before pinning':p.pinned?'Unpin promotion':'Pin promotion as a hot offer'} onClick={()=>togglePromotionPin(p)}>{!p.published?'Publish first':p.pinned?'Unpin':'📌 Pin'}</button><button type="button" title="Move up" onClick={()=>movePromotion(p,-10)}>↑</button><button type="button" title="Move down" onClick={()=>movePromotion(p,10)}>↓</button><button type="button" title="Edit" onClick={()=>setEditingPromotion(p)}>✎</button><button type="button" title="Delete" onClick={()=>removePromotion(p.id)}>×</button></div></article>):<p className="muted">No promotions yet. Add a sponsor, affiliate, shop, website, or media link.</p>}</div></section><PhonePreview products={data.products} promotions={data.promotions} currency={data.store.currency} account={account} design={design} editable onToggleProductPin={toggleProductPin} onTogglePromotionPin={togglePromotionPin}/></div>:tab==='Landing Pages'?<LandingPageEditor design={design} setDesign={setDesign} save={saveDesign} products={data.products} promotions={data.promotions} currency={data.store.currency} account={account}/>:<DesignEditor design={design} setDesign={setDesign} save={saveDesign} products={data.products} promotions={data.promotions} currency={data.store.currency} account={account}/>}
  {open&&<ProductModal initial={open===true?null:open} types={data.product_types} account={account} store={data.store} design={design} close={()=>setOpen(false)} saved={()=>{setOpen(false);reload()}}/>}
  {editingPromotion&&<PromotionModal initial={editingPromotion} account={account} store={data.store} design={design} close={()=>setEditingPromotion(null)} saved={()=>{setEditingPromotion(null);reload()}}/>}
  </>}

function ProductModal({initial,types,account,store,design,close,saved}){
  const initialType=initial?.type||'digital-download';
  const [form,setForm]=useState(()=>({type:initialType,title:initial?.title||'',subtitle:initial?.subtitle||'',description:initial?.description||'',callToAction:initial?.call_to_action||'Get access',thumbnailStyle:initial?.thumbnail_style||'preview',priceRupees:initial?Number(initial.price_subunits)/100:0,status:initial?.status||'draft',position:initial?.position??10}));
  const [configuration,setConfiguration]=useState(()=>productConfiguration(initial||{type:initialType}));
  const [file,setFile]=useState(null),[fileKind,setFileKind]=useState(initialType==='course'?'lesson-video':'download'),[error,setError]=useState(''),[saving,setSaving]=useState(false);
  if(!initial&&form.type==='url-media')return <PromotionModal account={account} store={store} design={design} close={close} saved={saved} types={types} chooseType={type=>{setForm({...form,type});setConfiguration(defaultProductConfiguration(type))}}/>;
  const chooseType=type=>{setForm({...form,type,priceRupees:type==='lead-magnet'?0:form.priceRupees});setConfiguration(defaultProductConfiguration(type));setFileKind(type==='course'?'lesson-video':'download')};
  const submit=async e=>{e.preventDefault();setSaving(true);setError('');try{const {priceRupees,subtitle,callToAction,thumbnailStyle,...basic}=form;const product=await request(initial?`/api/v1/products/${initial.id}`:'/api/v1/products',{method:initial?'PATCH':'POST',body:JSON.stringify({...basic,priceSubunits:form.type==='lead-magnet'?0:Math.round(Number(priceRupees)*100)})});await request(`/api/v1/products/${product.id}/configuration`,{method:'PUT',body:JSON.stringify({subtitle,callToAction,thumbnailStyle,configuration})});if(file)await uploadProductFile(product.id,file,fileKind);saved()}catch(x){setError(x.message);setSaving(false)}};
  const preview={type:form.type,title:form.title||productVisual(form.type)[1],price_subunits:Math.round(Number(form.priceRupees||0)*100),status:'published'};
  return <div className="modal-backdrop"><form className="modal product-modal" onSubmit={submit}><section className="product-form-pane"><div className="modal-head"><div><span className="eyebrow">{initial?'Product builder':'New offer'}</span><h2>{initial?'Edit product or service':'Add a product'}</h2></div><button type="button" className="icon-button" onClick={close}>×</button></div><ProductTypePicker types={types} selected={form.type} choose={chooseType}/><fieldset className="builder-section"><legend>1. Storefront thumbnail</legend><div className="form-grid"><label>Card style<select value={form.thumbnailStyle} onChange={e=>setForm({...form,thumbnailStyle:e.target.value})}><option value="button">Button</option><option value="callout">Callout</option><option value="preview">Image preview</option></select></label><label>Button text<input required maxLength="60" value={form.callToAction} onChange={e=>setForm({...form,callToAction:e.target.value})}/></label></div><label>Title<input required maxLength="100" placeholder="Give your offer a clear name" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Subtitle<input maxLength="160" placeholder="A short storefront promise" value={form.subtitle} onChange={e=>setForm({...form,subtitle:e.target.value})}/></label></fieldset><fieldset className="builder-section"><legend>2. Checkout page</legend><label>Description<textarea required maxLength="2000" placeholder="What will your customer receive?" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label>{form.type!=='lead-magnet'&&<label>Price (₹ INR)<input type="number" min="0" step="0.01" value={form.priceRupees} onChange={e=>setForm({...form,priceRupees:e.target.value})}/><small>Saved server-side in paise; ₹1.00 = 100 paise.</small></label>}{form.type==='lead-magnet'&&<div className="type-notice">Lead magnets are free and collect customer information instead of charging a price.</div>}</fieldset><TypeSpecificFields type={form.type} configuration={configuration} setConfiguration={setConfiguration} file={file} setFile={setFile} fileKind={fileKind} setFileKind={setFileKind}/><fieldset className="builder-section"><legend>4. Publish</legend><label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="draft">Save as draft</option><option value="published">Publish to storefront</option></select></label></fieldset>{error&&<p className="error">{error}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving}>{saving?'Saving…':initial?'Save changes':'Save product'}</button></div></section><PhonePreview products={[]} promotions={[]} currency={store.currency} account={account} design={design} previewProduct={preview} compact/></form></div>
}

function TypeSpecificFields({type,configuration,setConfiguration,file,setFile,fileKind,setFileKind}){
  const set=(key,value)=>setConfiguration({...configuration,[key]:value});
  const number=(key,value)=>set(key,Number(value));
  if(type==='digital-download'||type==='lead-magnet')return <fieldset className="builder-section type-builder"><legend>3. {type==='lead-magnet'?'Lead capture and delivery':'Digital delivery'}</legend><div className="segmented"><button type="button" className={configuration.deliveryMode==='upload'?'selected':''} onClick={()=>set('deliveryMode','upload')}>Upload file</button><button type="button" className={configuration.deliveryMode==='redirect'?'selected':''} onClick={()=>set('deliveryMode','redirect')}>Redirect URL</button></div>{configuration.deliveryMode==='upload'?<label>Product file<input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/><small>{file?`${file.name} selected`:'PDF, ZIP, video, template, or other downloadable file; up to 500 MB locally.'}</small></label>:<label>Secure destination URL<input required type="url" pattern="https://.*" value={configuration.redirectUrl||''} onChange={e=>set('redirectUrl',e.target.value)} placeholder="https://drive.example/resource"/></label>}{type==='lead-magnet'&&<label className="check-row"><input type="checkbox" checked={Boolean(configuration.collectPhone)} onChange={e=>set('collectPhone',e.target.checked)}/> Also collect phone number</label>}</fieldset>;
  if(type==='meeting')return <fieldset className="builder-section type-builder"><legend>3. Coaching availability</legend><div className="form-grid"><label>Meeting location<select value={configuration.location||'google-meet'} onChange={e=>set('location',e.target.value)}><option value="google-meet">Google Meet</option><option value="zoom">Zoom</option><option value="custom">Custom / in person</option></select></label><label>Timezone<input required value={configuration.timezone||''} onChange={e=>set('timezone',e.target.value)}/></label><label>Duration (minutes)<input type="number" min="15" max="480" value={configuration.durationMinutes||60} onChange={e=>number('durationMinutes',e.target.value)}/></label><label>Maximum attendees<input type="number" min="1" max="500" value={configuration.maxAttendees||1} onChange={e=>number('maxAttendees',e.target.value)}/></label><label>Minimum notice (hours)<input type="number" min="0" value={configuration.minNoticeHours||0} onChange={e=>number('minNoticeHours',e.target.value)}/></label><label>Buffer (minutes)<input type="number" min="0" value={configuration.bufferMinutes||0} onChange={e=>number('bufferMinutes',e.target.value)}/></label></div><label>Available times<textarea value={configuration.availability||''} onChange={e=>set('availability',e.target.value)} placeholder="Monday-Friday, 9:00 AM-5:00 PM"/></label></fieldset>;
  if(type==='webinar')return <fieldset className="builder-section type-builder"><legend>3. Configure webinar</legend><div className="form-grid"><label>Location<select value={configuration.location||'google-meet'} onChange={e=>set('location',e.target.value)}><option value="google-meet">Google Meet</option><option value="zoom">Zoom</option><option value="custom">Custom location</option></select></label><label>Start date and time<input required type="datetime-local" value={configuration.startsAt||''} onChange={e=>set('startsAt',e.target.value)}/></label><label>Duration (minutes)<input type="number" min="15" max="480" value={configuration.durationMinutes||60} onChange={e=>number('durationMinutes',e.target.value)}/></label><label>Attendee capacity<input type="number" min="1" max="100000" value={configuration.capacity||100} onChange={e=>number('capacity',e.target.value)}/></label></div></fieldset>;
  if(type==='course')return <fieldset className="builder-section type-builder"><legend>3. Course modules and lessons</legend><CourseModules modules={configuration.modules||[]} change={modules=>set('modules',modules)}/><div className="form-grid"><label>Drip delay (days)<input type="number" min="0" value={configuration.dripDays||0} onChange={e=>number('dripDays',e.target.value)}/></label><label>Upload asset type<select value={fileKind} onChange={e=>setFileKind(e.target.value)}><option value="lesson-video">Lesson video</option><option value="supporting-material">Supporting PDF/material</option></select></label></div><label>Course file<input type="file" accept="video/*,.pdf,.ppt,.pptx,.zip" onChange={e=>setFile(e.target.files?.[0]||null)}/><small>{file?`${file.name} selected`:'Upload a lesson video or supporting material after saving.'}</small></label></fieldset>;
  if(type==='membership')return <fieldset className="builder-section type-builder"><legend>3. Membership access</legend><label>Billing frequency<select value={configuration.billingInterval||'monthly'} onChange={e=>set('billingInterval',e.target.value)}><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="annual">Annual</option></select></label><label>Member benefits<textarea required value={configuration.memberBenefits||''} onChange={e=>set('memberBenefits',e.target.value)} placeholder="Exclusive lessons, downloads, live calls…"/></label></fieldset>;
  if(type==='fulfillment')return <fieldset className="builder-section type-builder"><legend>3. Custom fulfillment</legend><div className="form-grid"><label>Delivery within (days)<input type="number" min="1" max="365" value={configuration.turnaroundDays||3} onChange={e=>number('turnaroundDays',e.target.value)}/></label><label>Delivery format<select value={configuration.deliveryFormat||'file-upload'} onChange={e=>set('deliveryFormat',e.target.value)}><option value="file-upload">Upload result</option><option value="email">Email delivery</option><option value="call">Scheduled call</option></select></label></div><label>Buyer instructions<textarea value={configuration.buyerInstructions||''} onChange={e=>set('buyerInstructions',e.target.value)} placeholder="Ask the buyer for the information needed to complete the work."/></label></fieldset>;
  if(type==='community')return <fieldset className="builder-section type-builder"><legend>3. Community access</legend><label>Member benefits<textarea required value={configuration.memberBenefits||''} onChange={e=>set('memberBenefits',e.target.value)} placeholder="Channels, resources, calls, and access included"/></label><label>Welcome message<textarea value={configuration.welcomeMessage||''} onChange={e=>set('welcomeMessage',e.target.value)}/></label></fieldset>;
  return null;
}

function CourseModules({modules,change}){const update=(index,key,value)=>change(modules.map((m,i)=>i===index?{...m,[key]:value}:m));const updateLesson=(moduleIndex,lessonIndex,key,value)=>change(modules.map((m,i)=>i===moduleIndex?{...m,lessons:(m.lessons||[]).map((l,j)=>j===lessonIndex?{...l,[key]:value}:l)}:m));return <div className="course-modules">{modules.map((module,moduleIndex)=><section key={moduleIndex}><div className="module-head"><input aria-label={`Module ${moduleIndex+1} title`} value={module.title} onChange={e=>update(moduleIndex,'title',e.target.value)}/><button type="button" onClick={()=>change(modules.filter((_,i)=>i!==moduleIndex))}>Remove</button></div>{(module.lessons||[]).map((lesson,lessonIndex)=><div className="lesson-row" key={lessonIndex}><input aria-label={`Lesson ${lessonIndex+1} title`} placeholder="Lesson title" value={lesson.title} onChange={e=>updateLesson(moduleIndex,lessonIndex,'title',e.target.value)}/><input aria-label={`Lesson ${lessonIndex+1} video URL`} type="url" placeholder="Optional HTTPS video URL" value={lesson.videoUrl||''} onChange={e=>updateLesson(moduleIndex,lessonIndex,'videoUrl',e.target.value)}/></div>)}<button type="button" className="text-button" onClick={()=>update(moduleIndex,'lessons',[...(module.lessons||[]),{title:`Lesson ${(module.lessons||[]).length+1}`,videoUrl:'',description:''}])}>＋ Add lesson</button></section>)}<button type="button" className="secondary" onClick={()=>change([...modules,{title:`Module ${modules.length+1}`,lessons:[]}])}>＋ Add module</button></div>}

function ProductTypePicker({types,selected,choose}){return <fieldset className="product-type-fieldset"><legend>What would you like to offer?</legend><div className="product-type-grid">{types.map(type=>{const visual=productVisual(type);return <button type="button" aria-pressed={selected===type} className={selected===type?'selected':''} onClick={()=>choose(type)} key={type}><i>{visual[0]}</i><span><b>{visual[1]}</b><small>{visual[2]}</small></span></button>})}</div></fieldset>}

const promotionPayload=form=>({title:form.title,url:form.url,description:form.description||'',brandName:form.brandName??form.brand_name??'',thumbnailUrl:form.thumbnailUrl??form.thumbnail_url??'',callToAction:form.callToAction??form.call_to_action??'Shop now',couponCode:form.couponCode??form.coupon_code??'',offerText:form.offerText??form.offer_text??'',disclosure:form.disclosure||'',position:Number(form.position||0),published:Boolean(form.published),startsAt:form.startsAt??form.starts_at??null,endsAt:form.endsAt??form.ends_at??null});
const dateTimeValue=value=>value?String(value).slice(0,16):'';
function PromotionModal({initial,account,store,design,close,saved,types,chooseType}){const [form,setForm]=useState(()=>({title:initial?.title||'',url:initial?.url||'',description:initial?.description||'',brandName:initial?.brand_name||'',thumbnailUrl:initial?.thumbnail_url||'',callToAction:initial?.call_to_action||'Shop now',couponCode:initial?.coupon_code||'',offerText:initial?.offer_text||'',disclosure:initial?.disclosure||'#ad · Affiliate link',position:initial?.position??10,published:initial?.published??false,startsAt:dateTimeValue(initial?.starts_at),endsAt:dateTimeValue(initial?.ends_at)})),[error,setError]=useState('');const submit=async e=>{e.preventDefault();try{const payload=promotionPayload({...form,startsAt:form.startsAt?new Date(form.startsAt).toISOString():null,endsAt:form.endsAt?new Date(form.endsAt).toISOString():null});await request(initial?`/api/v1/promotions/${initial.id}`:'/api/v1/promotions',{method:initial?'PATCH':'POST',body:JSON.stringify(payload)});saved()}catch(x){setError(x.message)}};const preview={...promotionPayload(form),brand_name:form.brandName,call_to_action:form.callToAction,coupon_code:form.couponCode,offer_text:form.offerText};return <div className="modal-backdrop"><form className="modal product-modal" onSubmit={submit}><section className="product-form-pane"><div className="modal-head"><div><span className="eyebrow">Outbound offer</span><h2>{initial?'Edit promotion':'Add promotion or link'}</h2></div><button type="button" className="icon-button" onClick={close}>×</button></div>{types&&<ProductTypePicker types={types} selected="url-media" choose={chooseType}/>}<div className="form-grid"><label>Promotion name<input required maxLength="100" placeholder="25% off Glow Beauty Cream" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Brand or sponsor<input maxLength="100" placeholder="Glow Beauty" value={form.brandName} onChange={e=>setForm({...form,brandName:e.target.value})}/></label></div><label>Destination URL<input required type="url" pattern="https://.*" placeholder="https://merchant.example/creator-offer" value={form.url} onChange={e=>setForm({...form,url:e.target.value})}/><small>HTTPS only. Visitors leave your store and complete the purchase with the merchant.</small></label><label>Description<textarea maxLength="500" placeholder="Tell visitors what the offer includes." value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Image URL<input type="url" pattern="https://.*" placeholder="https://cdn.example/image.jpg" value={form.thumbnailUrl} onChange={e=>setForm({...form,thumbnailUrl:e.target.value})}/></label><div className="form-grid"><label>Button text<input required maxLength="60" value={form.callToAction} onChange={e=>setForm({...form,callToAction:e.target.value})}/></label><label>Offer text<input maxLength="120" placeholder="25% off" value={form.offerText} onChange={e=>setForm({...form,offerText:e.target.value})}/></label><label>Coupon code<input maxLength="80" placeholder="GLOW25" value={form.couponCode} onChange={e=>setForm({...form,couponCode:e.target.value.toUpperCase()})}/></label><label>Disclosure<input maxLength="160" value={form.disclosure} onChange={e=>setForm({...form,disclosure:e.target.value})}/></label><label>Starts at<input type="datetime-local" value={form.startsAt} onChange={e=>setForm({...form,startsAt:e.target.value})}/></label><label>Ends at<input type="datetime-local" value={form.endsAt} onChange={e=>setForm({...form,endsAt:e.target.value})}/></label></div><label className="check-row"><input type="checkbox" checked={form.published} onChange={e=>setForm({...form,published:e.target.checked})}/> Publish immediately (subject to schedule)</label>{error&&<p className="error">{error}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">{initial?'Save changes':form.published?'Publish promotion':'Save draft'}</button></div></section><PhonePreview products={[]} promotions={[]} currency={store.currency} account={account} design={design} previewPromotion={preview} compact/></form></div>}

const storefrontFeed=(products,links,design)=>[
  ...(design.showProducts?products.map(item=>({...item,feedKind:'product'})):[]),
  ...(design.showLinks?links.map(item=>({...item,feedKind:'promotion'})):[])
].sort((a,b)=>Number(Boolean(b.pinned))-Number(Boolean(a.pinned))||Number(a.position||0)-Number(b.position||0)||Number(a.id||0)-Number(b.id||0));

function PhonePreview({products=[],promotions=[],currency,account,design=designFromStore({}),previewProduct,previewPromotion,compact=false,editable=false,onToggleProductPin,onTogglePromotionPin}){const visible=previewProduct?[previewProduct]:products.filter(x=>x.status==='published');const links=previewPromotion?[previewPromotion]:promotions.filter(x=>x.published);const feed=storefrontFeed(visible,links,design);const toggle=item=>item.feedKind==='product'?onToggleProductPin?.(item):onTogglePromotionPin?.(item);return <aside className={`preview-panel ${compact?'compact':''}`}><span>Live phone preview</span>{editable&&<small className="preview-help">Pin a deal here to move it to the top for visitors.</small>}<div className={`phone background-${design.backgroundStyle} buttons-${design.buttonStyle} font-${design.fontStyle}`} style={{'--store-accent':design.accentColor}}><div className="phone-speaker"/><div className="phone-profile"><div className="avatar" style={{background:design.accentColor}}>{design.title?.[0]||account.displayName?.[0]||'C'}</div><b>{design.title||account.displayName}</b><small>@{account.handle}</small><p>{design.tagline}</p></div>{feed.map((x,index)=>x.feedKind==='product'?(()=>{const visual=productVisual(x.type);return <div className={`mini-product ${x.pinned?'phone-pinned':''}`} key={`product-${x.id||index}`}><i>{visual[0]}</i><span><b>{x.pinned&&<em className="phone-hot-badge">HOT</em>}{x.title}</b><small>{visual[1]}</small></span><strong>{money(x.price_subunits,currency)}</strong>{editable&&<button type="button" className="phone-pin-action" title={x.pinned?'Unpin product':'Pin product'} onClick={()=>toggle(x)}>{x.pinned?'Unpin':'📌 Pin'}</button>}</div>})():<div className={`mini-link promotion ${x.pinned?'phone-pinned':''}`} key={`promotion-${x.id||index}`}><span><b>{x.pinned&&<em className="phone-hot-badge">HOT</em>}{x.title||'Promotion'}</b><small>{x.offer_text||x.brand_name||'External link'}</small></span><strong>{x.call_to_action||'Visit'} ↗</strong>{editable&&<button type="button" className="phone-pin-action" title={x.pinned?'Unpin promotion':'Pin promotion'} onClick={()=>toggle(x)}>{x.pinned?'Unpin':'📌 Pin'}</button>}</div>)}{!feed.length&&<div className="phone-empty">Your products and promotions will appear here</div>}</div></aside>}

function LandingPageEditor({design,setDesign,save,products,promotions,currency,account}){const [message,setMessage]=useState('');const submit=async e=>{e.preventDefault();try{await save(design);setMessage('Landing page saved. Your public store now uses this content.')}catch(x){setMessage(x.message)}};return <div className="editor-layout"><form className="panel storefront-editor" onSubmit={submit}><span className="eyebrow">Public storefront content</span><h2>Landing page</h2><p className="muted">Choose what visitors see. This changes your public store, not your private dashboard.</p><label>Store headline<input required maxLength="100" value={design.title} onChange={e=>setDesign({...design,title:e.target.value})}/></label><label>Short introduction<textarea maxLength="180" value={design.tagline} onChange={e=>setDesign({...design,tagline:e.target.value})}/><small>{design.tagline.length}/180 characters</small></label><div className="visibility-options"><label><input type="checkbox" checked={design.showProducts} onChange={e=>setDesign({...design,showProducts:e.target.checked})}/> Show products</label><label><input type="checkbox" checked={design.showLinks} onChange={e=>setDesign({...design,showLinks:e.target.checked})}/> Show featured links</label></div><div className="editor-note"><b>Section order</b><span>Profile → Featured offers</span><small>Pinned products and promotions are shown first in one visitor feed.</small></div><button className="primary">Save landing page</button>{message&&<p className="save-message">{message}</p>}</form><PhonePreview products={products} promotions={promotions} currency={currency} account={account} design={design}/></div>}

function DesignEditor({design,setDesign,save,products,promotions,currency,account}){const [message,setMessage]=useState('');const chooseTheme=key=>setDesign({...design,theme:key,accentColor:THEME_PRESETS[key].accent});const submit=async e=>{e.preventDefault();try{await save(design);setMessage('Design saved and published to your storefront preview.')}catch(x){setMessage(x.message)}};return <div className="editor-layout"><form className="panel storefront-editor" onSubmit={submit}><span className="eyebrow">Brand appearance</span><h2>Edit design</h2><p className="muted">Customize the public page your customers see.</p><fieldset className="theme-picker"><legend>Theme</legend>{Object.entries(THEME_PRESETS).map(([key,value])=><button type="button" className={design.theme===key?'selected':''} aria-pressed={design.theme===key} onClick={()=>chooseTheme(key)} key={key}><i style={{background:value.accent}}/><span>{value.label}</span></button>)}</fieldset><label>Custom accent color<div className="color-input"><input type="color" value={design.accentColor} onChange={e=>setDesign({...design,accentColor:e.target.value})}/><code>{design.accentColor}</code></div></label><label>Background<select value={design.backgroundStyle} onChange={e=>setDesign({...design,backgroundStyle:e.target.value})}><option value="soft-gradient">Soft gradient</option><option value="solid">Clean solid</option><option value="spotlight">Spotlight</option></select></label><label>Button shape<select value={design.buttonStyle} onChange={e=>setDesign({...design,buttonStyle:e.target.value})}><option value="rounded">Rounded</option><option value="pill">Pill</option><option value="square">Square</option></select></label><label>Typography<select value={design.fontStyle} onChange={e=>setDesign({...design,fontStyle:e.target.value})}><option value="modern">Modern</option><option value="editorial">Editorial</option><option value="friendly">Friendly</option></select></label><button className="primary">Save design</button>{message&&<p className="save-message">{message}</p>}</form><PhonePreview products={products} promotions={promotions} currency={currency} account={account} design={design}/></div>}

function Success({data}){return <><PageHead title="Success" subtitle="Short, practical lessons for building your creator business."/><div className="hero-card"><span className="eyebrow">Creator playbook</span><h2>Build an offer people understand in five seconds.</h2><p>Start with one outcome, one audience, and one clear next step.</p><button>Continue learning</button></div><div className="tutorial-grid">{data.tutorials.map((x,i)=><article key={x.id}><div className={`lesson-art art-${i}`}>▶</div><span>{x.category}</span><h3>{x.title}</h3><small>{x.minutes} min lesson</small></article>)}</div></>}

function Income({data}){return <><PageHead title="Income" subtitle="Track real-world INR revenue, fees, cashouts, and verified customer orders." actions={<button className="secondary">Export CSV</button>}/><div className="real-money-banner">REAL MONEY · Values are stored in paise. Gateway webhooks are the payment source of truth.</div><div className="metrics"><Metric label="Gross revenue" value={money(data.summary.gross_subunits,data.currency)}/><Metric label="Net revenue" value={money(data.summary.net_subunits,data.currency)}/><Metric label="Available to cash out" value={money(data.cashout.available_subunits,data.currency)}/><Metric label="Paid orders" value={data.summary.order_count}/></div><section className="panel chart-panel"><h2>Revenue</h2><div className="chart"><i style={{height:'25%'}}/><i style={{height:'48%'}}/><i style={{height:'38%'}}/><i style={{height:'72%'}}/><i style={{height:'56%'}}/><i style={{height:'86%'}}/><i style={{height:'64%'}}/></div></section><Table headers={['Order','Customer','Product','Gross','Status']} rows={data.orders.map(x=>[x.id,x.customer,x.product,money(x.amount_subunits,data.currency),x.status])}/></>}

function Analytics({data}){const t=data.totals;return <><PageHead title="Analytics" subtitle="Understand traffic, leads, conversion, sales, and outbound promotions."/><div className="metrics"><Metric label="Visits" value={t.visits}/><Metric label="Leads" value={t.leads}/><Metric label="Orders" value={t.orders}/><Metric label="Conversion" value={`${t.visits?Math.round(t.orders/t.visits*100):0}%`}/></div><div className="two-column"><section className="panel chart-panel"><h2>Store activity</h2><div className="line-chart"><svg viewBox="0 0 600 180"><path d="M0 150 C80 145 70 100 150 110 S250 135 320 70 S430 95 600 20" fill="none" stroke="currentColor" strokeWidth="6"/><path d="M0 150 C80 145 70 100 150 110 S250 135 320 70 S430 95 600 20 L600 180 L0 180Z"/></svg></div></section><section className="panel"><h2>Traffic sources</h2>{data.sources.length?data.sources.map(x=><div className="source" key={x.source}><b>{x.source}</b><span>{x.visits} visits</span></div>):<p className="muted">No source data yet.</p>}</section></div><Table headers={['Promotion','Brand','Clicks','Referrer groups','Status','Last click']} rows={(data.promotions||[]).map(x=>[x.title,x.brand_name||'—',x.clicks,x.sources,x.published?'Published':'Draft',x.last_clicked_at?new Date(x.last_clicked_at).toLocaleString():'—'])}/></>}

function Customers({data,reload}){const [open,setOpen]=useState(false);return <><PageHead title="Customers" subtitle={`${data.items.length} contacts · up to ${data.limit.toLocaleString()} in this plan`} actions={<><button className="secondary">Import CSV</button><button className="primary" onClick={()=>setOpen(true)}>＋ Add contact</button></>}/><div className="search"><input placeholder="Search name or email"/><button>Filter</button></div><Table headers={['Customer','Email','Source','Joined']} rows={data.items.map(x=>[x.name,x.email,x.source,new Date(x.created_at).toLocaleDateString()])}/>{open&&<CustomerModal close={()=>setOpen(false)} saved={()=>{setOpen(false);reload()}}/>}</>}

function CustomerModal({close,saved}){const [form,setForm]=useState({name:'',email:'',phone:''}),[error,setError]=useState('');const submit=async e=>{e.preventDefault();try{await request('/api/v1/customers',{method:'POST',body:JSON.stringify(form)});saved()}catch(x){setError(x.message)}};return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="modal-head"><h2>Add contact</h2><button type="button" className="icon-button" onClick={close}>×</button></div>{['name','email','phone'].map(k=><label key={k}>{k[0].toUpperCase()+k.slice(1)}<input required={k!=='phone'} type={k==='email'?'email':'text'} value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}{error&&<p className="error">{error}</p>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">Add contact</button></div></form></div>}

function Community(){return <><PageHead title="Community" subtitle="Learn with other creators and share practical wins."/><div className="community-hero"><div><span className="eyebrow">Creator Foundations</span><h2>Build alongside 1,248 creators.</h2><p>Weekly conversations about offers, audience growth, and sustainable systems.</p><button>Join community</button></div><div className="people">{['M','J','K','S','R'].map(x=><span key={x}>{x}</span>)}</div></div><div className="two-column"><section className="panel"><h2>Popular this week</h2><div className="thread"><b>What changed your conversion rate?</b><small>42 replies · 2h ago</small></div><div className="thread"><b>Show your storefront</b><small>87 replies · 1d ago</small></div></section><section className="panel"><h2>Upcoming</h2><div className="thread"><b>Offer teardown workshop</b><small>Thursday · 12:00 PM</small></div></section></div></>}

function More(){const cards=[['⇄','Funnels','Connect offers into a guided customer journey.'],['◷','Appointments','Manage availability and bookings.'],['♧','Referrals','Reward partners who drive sales.'],['✉','Email Flows','Automate customer follow-up.']];return <><PageHead title="More tools" subtitle="Add growth and automation capabilities when you need them."/><div className="feature-grid">{cards.map(x=><article key={x[1]}><i>{x[0]}</i><div><h3>{x[1]}</h3><p>{x[2]}</p></div><button>Open →</button></article>)}</div><AutoDmRules/></>}

function AutoDmRules(){const empty={instagramAccountId:'',mediaId:'',keywords:'',matchMode:'any',replyText:'',active:false};const [rules,setRules]=useState([]),[form,setForm]=useState(empty),[message,setMessage]=useState('');const load=()=>request('/api/v1/automations/instagram-comment-rules').then(setRules).catch(e=>setMessage(e.message));useEffect(()=>{load()},[]);const submit=async e=>{e.preventDefault();setMessage('');try{await request('/api/v1/automations/instagram-comment-rules',{method:'POST',body:JSON.stringify({...form,keywords:form.keywords.split(',').map(x=>x.trim()).filter(Boolean)})});setForm(empty);setMessage('Rule saved. It will act only after the Meta app, webhook, token, and worker are configured.');load()}catch(x){setMessage(x.message)}};return <section className="panel settings-form"><div className="real-money-banner">EXTERNAL INSTAGRAM ACTION · One private reply per matching comment; Meta controls eligibility and timing.</div><h2>Comment-to-DM automation</h2><form onSubmit={submit}><label>Instagram professional account ID<input required value={form.instagramAccountId} onChange={e=>setForm({...form,instagramAccountId:e.target.value})}/></label><label>Instagram media ID<input required value={form.mediaId} onChange={e=>setForm({...form,mediaId:e.target.value})}/></label><label>Keywords (comma separated)<input required value={form.keywords} onChange={e=>setForm({...form,keywords:e.target.value})}/></label><label>Match mode<select value={form.matchMode} onChange={e=>setForm({...form,matchMode:e.target.value})}><option value="any">Any keyword</option><option value="all">All keywords</option><option value="exact">Exact comment</option></select></label><label>Private reply<textarea required maxLength="1000" value={form.replyText} onChange={e=>setForm({...form,replyText:e.target.value})}/></label><label><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/> Activate after saving</label><button className="primary">Save AutoDM rule</button></form>{message&&<p className="muted">{message}</p>}<div className="provider-stack">{rules.map(rule=><div className="connection" key={rule.id}><i>{rule.active?'✓':'○'}</i><div><b>Media {rule.media_id}</b><small>{String(rule.keywords).split('\n').join(', ')} · {rule.match_mode}</small></div><span className={`status ${rule.active?'published':'draft'}`}>{rule.active?'active':'draft'}</span></div>)}</div></section>}

function Settings({data}){const [tab,setTab]=useState('profile'),[payments,setPayments]=useState(null),[instagram,setInstagram]=useState(null);useEffect(()=>{request('/api/v1/payments/config').then(setPayments);request('/api/v1/integrations/instagram/config').then(setInstagram)},[]);return <><PageHead title="Settings" subtitle="Manage your account, store, payments, and security."/><div className="settings-layout"><nav>{data.tabs.map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x.replaceAll('-',' ')}</button>)}</nav><section className="panel settings-form"><h2>{tab.replaceAll('-',' ')}</h2>{tab==='profile'?<><label>Display name<input defaultValue={data.profile.display_name}/></label><label>Username<div className="prefix-input"><span>creator.test/</span><input defaultValue={data.profile.username}/></div></label><label>Bio<textarea defaultValue={data.profile.bio}/></label><button className="primary">Save changes</button></>:tab==='payments'?<ProviderSettings payments={payments} payouts={data.store.payouts_enabled}/>:tab==='integrations'?<IntegrationSettings instagram={instagram}/>:<State title={`${tab.replaceAll('-',' ')} settings`} body="The API boundary and navigation are implemented; provider credentials belong in local untracked environment files or AWS Secrets Manager."/>}</section></div></>}

function ProviderSettings({payments,payouts}){if(!payments)return <p>Loading provider status…</p>;return <div className="provider-stack"><div className="real-money-banner">REAL MONEY · {payments.mode.toUpperCase()} MODE · {payments.smallest_unit.toUpperCase()}</div>{payments.providers.map(p=><div className="connection" key={p.id}><i>{p.configured?'✓':'!'}</i><div><b>{p.label}{p.india_primary?' · India primary':''}</b><small>{p.configured?'Credentials detected server-side':`Not configured · no ${p.label} charge can be created`}</small></div><span className={`status ${p.configured?'published':'draft'}`}>{p.configured?payments.mode:'disabled'}</span></div>)}<p className="muted">Payout readiness: {payouts?'enabled':'setup required'}. Secrets are never returned to this browser.</p></div>}
function IntegrationSettings({instagram}){if(!instagram)return <p>Loading integration status…</p>;const permissions=instagram.required_permissions||[instagram.required_permission].filter(Boolean);return <div className="provider-stack"><div className="connection"><i>{instagram.configured?'✓':'!'}</i><div><b>Instagram professional messaging</b><small>{instagram.notice}</small></div><span className={`status ${instagram.configured?'published':'draft'}`}>{instagram.mode}</span></div><p className="muted">Permissions: {permissions.join(', ')||'not configured'} · allowlisted test recipients: {instagram.test_recipient_count}</p></div>}

function PublicStore(){const handle=location.pathname.replace(/^\//,'')||'alex';const [page,setPage]=useState(null),[missing,setMissing]=useState(false);useEffect(()=>{request(`/api/public/${handle}`).then(setPage).catch(()=>setMissing(true))},[handle]);if(missing)return <Signup/>;if(!page)return <div className="public-loading">Loading store…</div>;const design=designFromStore(page.store);const feed=storefrontFeed(page.products,page.links,design);const visitPromotion=async link=>{try{await request('/api/events/click',{method:'POST',body:JSON.stringify({linkId:link.id,creatorId:page.creator.id,path:location.pathname,referrer:document.referrer||null,campaign:new URL(link.url).searchParams.get('utm_campaign')})})}finally{location.assign(link.url)}};return <main className={`public-store background-${design.backgroundStyle} buttons-${design.buttonStyle} font-${design.fontStyle}`} style={{'--store-accent':design.accentColor}}><div className="public-profile"><div className="avatar" style={{background:design.accentColor}}>{design.title?.[0]||page.creator.display_name[0]}</div><h1>{design.title||page.creator.display_name}</h1><p>@{page.creator.handle}</p><p>{design.tagline||page.creator.bio}</p></div><div className="public-feed public-products">{feed.map(item=>item.feedKind==='product'?<PublicProductCard product={item} creatorId={page.creator.id} currency={page.store.currency} key={`product-${item.id}`}/>:<PublicPromotionCard promotion={item} visit={visitPromotion} key={`promotion-${item.id}`}/>)}</div><small>Powered by Creator Store · Sponsored and affiliate offers are clearly disclosed</small></main>}

function PublicProductCard({product,creatorId,currency}){const visual=productVisual(product.type);return <article className={product.pinned?'public-pinned':''}><div className="public-art">{visual[0]}</div><div><span className="product-kind">{product.pinned?'📌 Hot deal · ':''}{visual[1]}</span><h2>{product.title}</h2><p>{product.description}</p><b>{money(product.price_subunits,currency)}</b></div><CheckoutAction product={product} creatorId={creatorId}/></article>}

function PublicPromotionCard({promotion,visit}){return <article className={`promotion-card ${promotion.pinned?'public-pinned':''}`}>{promotion.thumbnail_url?<img src={promotion.thumbnail_url} alt=""/>:<div className="public-art">🏷️</div>}<div><span className="product-kind">{promotion.pinned?'📌 Hot deal · ':''}{promotion.brand_name||'Featured link'}</span><h2>{promotion.title}</h2>{promotion.description&&<p>{promotion.description}</p>}<div className="promotion-meta">{promotion.offer_text&&<strong>{promotion.offer_text}</strong>}{promotion.coupon_code&&<code>{promotion.coupon_code}</code>}</div>{promotion.disclosure&&<small>{promotion.disclosure}</small>}</div><button onClick={()=>visit(promotion)}>{promotion.call_to_action||'Visit link'} ↗</button></article>}

function CheckoutAction({product,creatorId}){const [message,setMessage]=useState(''),[buyerEmail,setBuyerEmail]=useState(''),[buyerName,setBuyerName]=useState('');const start=async()=>{if(!buyerEmail.includes('@')){setMessage('Enter a valid email for your receipt and access.');return}setMessage('Creating secure checkout…');try{const session=await request('/api/v1/checkout/sessions',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({creatorId,productId:product.id,buyerEmail,buyerName})});if(session.provider==='stripe'){location.assign(session.redirect_url);return}await loadScript(session.checkout_script);const checkout=new window.Razorpay({key:session.public_key_id,amount:session.amount_subunits,currency:session.currency,order_id:session.provider_session_id,name:'Creator Store',description:product.title,prefill:{name:buyerName,email:buyerEmail},handler:async result=>{await request('/api/v1/payments/razorpay/verify',{method:'POST',body:JSON.stringify({orderId:result.razorpay_order_id,paymentId:result.razorpay_payment_id,signature:result.razorpay_signature})});setMessage('Payment response verified. Final confirmation arrives by webhook.')}});checkout.open();setMessage('Razorpay checkout opened.') }catch(e){setMessage(e.message)}};return <div className="checkout-action"><input aria-label="Your name" placeholder="Your name" value={buyerName} onChange={e=>setBuyerName(e.target.value)}/><input aria-label="Your email" type="email" required placeholder="Your email" value={buyerEmail} onChange={e=>setBuyerEmail(e.target.value)}/><button onClick={start}>Buy securely</button>{message&&<small>{message}</small>}</div>}
function loadScript(src){return new Promise((resolve,reject)=>{if(document.querySelector(`script[src="${src}"]`))return resolve();const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(new Error('Could not load payment checkout.'));document.head.appendChild(script)})}

function Signup(){const [form,setForm]=useState({handle:'',displayName:'',email:'',phone:'',password:''}),[message,setMessage]=useState('');const submit=async e=>{e.preventDefault();try{await request('/api/auth/register',{method:'POST',body:JSON.stringify(form)});await request('/api/auth/login',{method:'POST',body:JSON.stringify({handleOrEmail:form.email,password:form.password})});location.assign('/dashboard/')}catch(x){setMessage(x.message)}};return <main className="signup"><span className="brand-mark">CS</span><h1>Create your creator store</h1><p>Publish links and sell digital offers from one page.</p><form onSubmit={submit}>{[['handle','Username'],['displayName','Display name'],['email','Email'],['phone','Phone (optional)'],['password','Password']].map(([k,l])=><label key={k}>{l}<input required={k!=='phone'} type={k==='password'?'password':k==='email'?'email':'text'} value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></label>)}<button className="primary">Create account</button></form>{message&&<p className="error">{message}</p>}<p>Already registered? <a href="/login">Sign in</a></p></main>}

function Login({onSuccess}){const [form,setForm]=useState({handleOrEmail:'',password:''}),[error,setError]=useState('');const submit=async e=>{e.preventDefault();try{onSuccess(await request('/api/auth/login',{method:'POST',body:JSON.stringify(form)}))}catch(x){setError(x.message)}};return <main className="signup"><span className="brand-mark">CS</span><h1>Sign in</h1><p>Use your creator handle or email.</p><form onSubmit={submit}><label>Handle or email<input required value={form.handleOrEmail} onChange={e=>setForm({...form,handleOrEmail:e.target.value})}/></label><label>Password<input required type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><button className="primary">Sign in</button></form>{error&&<p className="error">{error}</p>}</main>}

function Table({headers,rows}){return <section className="panel table-wrap"><table><thead><tr>{headers.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.length?rows.map((row,i)=><tr key={i}>{row.map((x,j)=><td key={j}>{x??'—'}</td>)}</tr>):<tr><td colSpan={headers.length} className="empty-cell">No data yet</td></tr>}</tbody></table></section>}
function State({title,body,action}){return <div className="empty-state"><span>◇</span><h2>{title}</h2><p>{body}</p>{action&&<button onClick={action}>Try again</button>}</div>}

const applicationRoot=globalThis.__creatorStoreRoot||(globalThis.__creatorStoreRoot=createRoot(document.getElementById('root')));
applicationRoot.render(<App/>);
